const express = require('express');
const { createStore } = require('redux');
const { authenticateCustomer } = require('../auth/customer');
const { Order } = require('../models/order');

const app = express();

function orderReducer(state = { activeOrder: null }, action) {
  if (action.type === 'SET_ORDER') return { activeOrder: action.payload };
  return state;
}

app.get('/ssr/checkout/orders/:orderId', authenticateCustomer, async (req, res) => {
  const { orderId } = req.params;

  // Verify that the requested order belongs to the authenticated customer
  const order = await Order.findOne({
    where: { id: orderId, customerId: req.user.id }
  });
  if (!order) return res.status(404).send('Order not found or access denied');

  // Create dedicated per-request Redux store
  const requestStore = createStore(orderReducer);

  requestStore.dispatch({
    type: 'SET_ORDER',
    payload: {
      orderId: order.id,
      shippingAddress: order.shippingAddress,
      customerPhone: order.customerPhone,
      cardLast4: order.cardLast4
    }
  });

  const html = `<script>window.__INITIAL_STATE__ = ${JSON.stringify(requestStore.getState())};</script><div>Shipping to ${order.shippingAddress.street}</div>`;
  res.send(html);
});

module.exports = app;
